head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf30002";
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const tmp_dtl_coupn_rt = $("#ipt_dtlCoupnRt", parent.opener.document).val();
        if (tmp_dtl_coupn_rt != null) {
            for (let r = 0, n = $c.util.getComponent('dlt_result').getRowCount(); r < n; r++) {const idx = r;
                const par_dtl_coupn_rt = $("#tbl_coupnRt > tbody", parent.opener.document).find("tr:eq(" + idx + ")").find("#dtl_coupn_rt").val();
                $c.util.getComponent('dlt_result').setCellData(r, 'coupnRt', par_dtl_coupn_rt);
            }
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf30002.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":5
        ,"mmenu":9
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf30002' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf30002.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_openStripYd_onclick
 * @description btn_openStripYd 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_openStripYd_onclick = async function(e){
    try {
        await scwin.openStripYd()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf30002.btn_openStripYd_onclick' }); }
};

/**
 * @method
 * @name btn_save_onclick
 * @description btn_save 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function(e){
    try {
        await scwin.save()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf30002.btn_save_onclick' }); }
};

/**
 * @method
 * @name btn_close_onclick
 * @description btn_close 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_close_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf30002.btn_close_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_openStripYd
 * @description open Strip Yd 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_openStripYd = async function () {
    const sbmOptions = {
        id: "tx_fn_openStripYd",
        method: "post",
        action: "/strip/strip.do?method=searchStripYdList",
        ref: "dma_openStripYdReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openStripYd
 * @description open Strip Yd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openStripYd = async function () {
    const width = 1000;
    const height = 800;
    const mtWidth = document.body.clientWidth;
    const mtHeight = document.body.clientHeight;
    const scX = 0;
    const scY = 0;
    const popX = scX + (mtWidth - width) / 2;
    const popY = scY + (mtHeight - height) / 2;
    let _previewWindow;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    _previewWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/strip/strip.do?method=searchStripYdList", unresolved: "nav:" + "/strip/strip.do?method=searchStripYdList" }; })();
    const fm = (document.searchForm || { elements: [] });
    const date = new Date();
    const year = date.getFullYear();
    const mm = ((date.getMonth() + 1) < 10 ? '0' + (date.getMonth() + 1) : (date.getMonth() + 1));
    const day = (date.getDate() < 10 ? '0' + date.getDate() : date.getDate());
    const today = year.toString() + "-" + mm.toString() + "-" + day.toString();
    $c.util.getComponent('dma_openStripYdReq').set('strtDd', today);
    fm.action = '/strip/strip.do?method=searchStripYdList';

    return;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    if (!await scwin.checkData()) {
        return;
    }
    const parentform = parent.opener.document;
    const newItem = $c.util.getComponent('coupnRtList').getValue();
    $("#tbl_coupnRt", parentform).empty().html(newItem);
    $("#tbl_coupnRt > tbody > tr", parentform).each(function(idx) {
            const data = $("#coupnRtList > tbody > tr:eq(" + idx + ") > td:eq(6)").find("#dtl_coupn_rt").val();
            $(this).find('td').eq(6).find("#dtl_coupn_rt").val(data);
    });
    $c.win.closePopup();
};

/**
 * @method
 * @name checkData
 * @description check Data 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkData = async function () {
    let returnYn = true;
    for (let r = 0, n = $c.util.getComponent('dlt_result').getRowCount(); r < n; r++) {const idx = r; /* 수동 전환 필요: DOM 관용구 $(this) 잔존 — 행 순회 안에서 해석 못 함(D19-b) */
        const rowIdx = idx + 1;
        if ($c.util.getComponent('dlt_result').getCellData(r, 'sprtParAmt') === '') {
            returnYn = false;
            await $c.win.alert(rowIdx + "번째 행의 분리신청액면금액을 입력하십시오");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        } else {
            if ($c.util.getComponent('dlt_result').getCellData(r, 'coupnRt') === '') {
                returnYn = false;
                await $c.win.alert(rowIdx + "번째 행의 표면이자율을 입력하십시오");
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return false;
            } else {
                if ($c.util.getComponent('dlt_result').getCellData(r, 'coupnRt') >= 100) {
                    returnYn = false;
                    await $c.win.alert(rowIdx + "번째 행의 표면이자율을 확인하십시오.");
                    /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                    return false;
                } else {
                    if (fn_minusCheck2($(this).find("#dtl_coupn_rt"), rowIdx + "번째 행의 표면이자율") === "N") {
                        returnYn = false;
                        return false;
                    }
                }
            }
        }
    }
    return returnYn;
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};
